        raise ``ValueError`` instead of producing a malformed encoding.
        """
        if not isinstance(self, MerklePublicKey):
            raise TypeError("to_bytes must be called on a MerklePublicKey")
        _validate_w(self.w)
        _validate_height(self.height)
